     1	package hotel.reservations;
     2	
     3	import hotel.reservations.plans.PricingSupport;
     4	import hotel.rooms.Room;
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	import java.time.LocalDate;
     8	import java.time.Month;
     9	import java.time.temporal.ChronoUnit;
    10	
    11	/**
    12	 * Turns a stay into money. The nightly primitives (every night costs the room's nightly rate, plus
    13	 * the high-season surcharge on high-season nights, rounded half-even to cents) live here; how the
    14	 * subtotal becomes a total belongs to the request's rate plan.
    15	 */
    16	public final class PriceCalculator implements PricingSupport {
    17	
    18	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    19	
    20	    public Price calculate(Room room, NewReservation request) {
    21	        return request.ratePlan().policy().price(room, request, this);
    22	    }
    23	
    24	    @Override
    25	    public int nights(LocalDate checkIn, LocalDate checkOut) {
    26	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    27	    }
    28	
    29	    @Override
    30	    public BigDecimal subtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    31	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    32	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    33	            subtotal = subtotal.add(nightPrice(room, night));
    34	        }
    35	        return subtotal;
    36	    }
    37	
    38	    BigDecimal nightPrice(Room room, LocalDate night) {
    39	        BigDecimal nightlyRate = room.nightlyRate();
    40	        if (isHighSeason(night)) {
    41	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    42	        }
    43	        return cents(nightlyRate);
    44	    }
    45	
    46	    /** High season: from December 15 to the end of February, and the whole of July. */
    47	    public static boolean isHighSeason(LocalDate date) {
    48	        Month month = date.getMonth();
    49	        return month == Month.JANUARY
    50	                || month == Month.FEBRUARY
    51	                || month == Month.JULY
    52	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    53	    }
    54	
    55	    @Override
    56	    public BigDecimal cents(BigDecimal value) {
    57	        return roundToCents(value);
    58	    }
    59	
    60	    public static BigDecimal roundToCents(BigDecimal value) {
    61	        return value.setScale(2, RoundingMode.HALF_EVEN);
    62	    }
    63	}
