   120	    }
   121	
   122	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   123	        return "Olá, " + reservation.guest().name() + "!\n\n"
   124	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   125	                + receipt.text() + "\n"
   126	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   127	                + "Até breve!\n";
   128	    }
   129	
   130	    private static HotelException notAllowed(Reservation reservation, String operation) {
