+    @Override
+    public BigDecimal cents(BigDecimal value) {
+        return roundToCents(value);
+    }
+
+    public static BigDecimal roundToCents(BigDecimal value) {
         return value.setScale(2, RoundingMode.HALF_EVEN);
     }
 }
